import fs from 'fs';
import path from 'path';
import os from 'os';
import {
  loadDataset,
  runEvaluations,
  generateReport,
  writeReport,
  toJson,
  toMarkdown
} from '/private/tmp/100-tricks-runs/d62/without/h2-eval-thresholds/r5/packages/frai-core/src/eval/index.js';

// Create test directory
const testDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-test-'));
console.log('Test directory:', testDir);

// Create test files
const outputsPath = path.join(testDir, 'outputs.json');
const referencesPath = path.join(testDir, 'references.json');

fs.writeFileSync(outputsPath, JSON.stringify(['Hello', 'World', 'Test'], null, 2));
fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world', 'test'], null, 2));

// Run evaluation pipeline
console.log('\n=== Running evaluation pipeline ===\n');

const dataset = loadDataset({ outputsPath, referencesPath });
console.log('Dataset loaded:', {
  outputsCount: dataset.outputs.length,
  referencesCount: dataset.references.length
});

const evaluations = runEvaluations({
  outputs: dataset.outputs,
  references: dataset.references
});

console.log('\nEvaluations results:');
evaluations.forEach((eval) => {
  console.log(`  ${eval.id}: ${eval.score} (${eval.total} samples)`);
});

// Test 1: No thresholds
console.log('\n=== Test 1: No thresholds ===');
const report1 = generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath
});
console.log('Report has passed field:', 'passed' in report1);
console.log('Report has thresholds field:', 'thresholds' in report1);

// Test 2: All thresholds pass
console.log('\n=== Test 2: All thresholds pass ===');
const report2 = generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath,
  thresholds: {
    exact_match: 0.8,
    toxicity: 0.9
  }
});
console.log('Passed:', report2.passed);
console.log('Thresholds:', report2.thresholds);

// Test 3: Thresholds fail
console.log('\n=== Test 3: At least one threshold fails ===');
const report3 = generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath,
  thresholds: {
    exact_match: 1.0  // This will fail
  }
});
console.log('Passed:', report3.passed);
console.log('Thresholds:', report3.thresholds);

// Test 4: Write JSON report
console.log('\n=== Test 4: Write JSON report ===');
const jsonPath = writeReport({
  report: report3,
  format: 'json',
  reportPath: path.join(testDir, 'report.json')
});
console.log('JSON report written to:', jsonPath);
const jsonContent = JSON.parse(fs.readFileSync(jsonPath, 'utf-8'));
console.log('JSON has passed field:', jsonContent.passed);
console.log('JSON has thresholds:', Array.isArray(jsonContent.thresholds));

// Test 5: Write Markdown report
console.log('\n=== Test 5: Write Markdown report ===');
const mdPath = writeReport({
  report: report3,
  format: 'markdown',
  reportPath: path.join(testDir, 'report.md')
});
console.log('Markdown report written to:', mdPath);
const mdContent = fs.readFileSync(mdPath, 'utf-8');
console.log('Markdown has Thresholds section:', mdContent.includes('## Thresholds'));
console.log('Markdown has PASS/FAIL:', mdContent.includes('PASS') || mdContent.includes('FAIL'));

// Cleanup
console.log('\n=== Cleanup ===');
fs.rmSync(testDir, { recursive: true, force: true });
console.log('Test directory cleaned up');
console.log('\n✓ All integration tests passed!');

